-- Kebold's Shiny: things around the window
--   * where a recipe is learned: trainers for your faction with a map pin, and where a recipe item comes from
--     (Places.lua, generated by make_addon_places.py; mostly original-game data, so Forever may have moved things)
--   * the selected recipe's cost, sale and profit at the profession window: a block inside the recipe pane
--     (LedgerPane.lua, the default) or the older strip above the window (settings().strip = "pane" | "top" | "off")
--   * a few lines on item tooltips: the scanned price, what making it costs, what a recipe item teaches
-- All of it only reads and shows. Each part is wrapped so that a client that lacks a function loses that part only.

local NS = KeboldsShinyNS
local UI = KeboldsShinyUI
local E = NS.E
local floor, max, min = math.floor, math.max, math.min
local DIM, RED, GOLD, WHITE, GREEN = NS.DIM, NS.RED, NS.GOLD, NS.WHITE, NS.GREEN
local money, itemName, settings, try = NS.money, NS.itemName, NS.settings, NS.try

local function signed(v)
  if v == nil then return DIM .. "-|r" end
  if v >= 0 then return GREEN .. "+" .. money(v) .. "|r" end
  return RED .. "-" .. money(-v) .. "|r"
end

-- ---- where a recipe is learned ------------------------------------------------------------------------------------

local function places()
  return type(KeboldsShinyPlaces) == "table" and KeboldsShinyPlaces or nil
end

-- "A", "H" or nil when the game does not say
local function mySide()
  if NS.side then return NS.side() end   -- the side plans are made for: the "Plan for" profile's, else the character's
  local f = try(UnitFactionGroup, "player")
  return (f == "Alliance" and "A") or (f == "Horde" and "H") or nil
end

local function open(side)
  local mine = mySide()
  return side == "B" or side == "" or side == nil or mine == nil or side == mine
end

local function npcOf(id)
  local P = places()
  local text = P and P.npcs and P.npcs[id]
  if not text then return nil end
  local f = E.split(text, "|")
  return { id = id, name = f[1], zone = f[2] or "", x = tonumber(f[3]), y = tonumber(f[4]), side = f[5] or "B" }
end

-- Trainers the collector has read in game: npc id -> { name, zone, map, x, y, side, spells = { [spell id] = true } }.
-- Such a trainer teaches exactly what his window listed, whatever the shipped lists say. A list the collector
-- marked `partial` (the window's filters could not be read, so it may leave recipes out) is not used for that.
local game, gameStamp
local function gameTrainers()
  local t = NS.collected().trainers
  if type(t) ~= "table" then return {} end
  local stamp = 0
  for _, rec in pairs(t) do stamp = stamp + (type(rec) == "table" and tonumber(rec.time) or 1) end
  if game and gameStamp == stamp then return game end
  game, gameStamp = {}, stamp
  for id, rec in pairs(t) do
    id = tonumber(id)
    if id and type(rec) == "table" and type(rec.list) == "table" and rec.partial ~= true then
      local spells, any = {}, false
      for _, line in ipairs(rec.list) do
        local s = tonumber((NS.fieldsOf(line, "|")[7] or ""):match("^1:(%d+)"))
        if s then
          spells[s] = true
          any = true
        end
      end
      if any then
        local w = NS.fieldsOf(rec.where, ";")
        local shipped = npcOf(id)
        local who = type(rec.player) == "string" and rec.player:match("^(%a+);") or nil
        game[id] = { id = id, name = rec.name or (shipped and shipped.name) or "?", zone = w[1] or "", map = tonumber(w[2]),
          x = tonumber(w[3]), y = tonumber(w[4]), spells = spells, seen = true,
          side = shipped and shipped.side or (who == "Alliance" and "A") or (who == "Horde" and "H") or "B" }
      end
    end
  end
  return game
end

-- Trainers that teach a recipe: the ones your faction can use (those in the zone you are in first), how many only
-- the other faction can use, and whether this is only the profession's general list (Forever teaches the recipe
-- at a trainer, but which trainer is not in any data). A trainer read in game is listed by what he really teaches.
local function trainersOf(r)
  local P = places()
  local groups = P and P.teach and P.teach[r.id]
  local out, other, seen = {}, 0, {}
  local read = gameTrainers()
  local general = P and P.fallback and P.fallback[r.prof]
  local anyTrainer = groups ~= nil and general ~= nil and groups == tostring(general)
  for g in (groups or ""):gmatch("%d+") do
    local ids = P.groups and P.groups[tonumber(g)]
    for id in (ids or ""):gmatch("%d+") do
      id = tonumber(id)
      if not seen[id] and not read[id] then
        seen[id] = true
        local n = npcOf(id)
        if n then
          if open(n.side) then out[#out + 1] = n else other = other + 1 end
        end
      end
    end
  end
  for id, n in pairs(read) do
    if n.spells[r.id] then
      anyTrainer = false   -- one trainer is known for certain
      if open(n.side) then out[#out + 1] = n else other = other + 1 end
    end
  end
  local here = try(GetRealZoneText) or ""
  table.sort(out, function(a, b)
    local ah, bh = a.zone == here, b.zone == here
    if ah ~= bh then return ah end
    if (a.zone == "") ~= (b.zone == "") then return b.zone == "" end   -- trainers with no known place go last
    if a.zone ~= b.zone then return a.zone < b.zone end
    return a.name < b.name
  end)
  return out, other, anyTrainer
end

local function whereIs(n)
  return n.zone ~= "" and n.zone or "place not known"
end

-- Vendors the collector has read in game: npc id -> { name, zone, map, x, y, who ("A" / "H" = the faction of the
-- character that opened him), items = { [item id] = { price = copper for one, left = number in stock or nil when
-- unlimited, other = true when the game asks for something besides money } } }.
-- The price is what the game showed that character, so a reputation discount is already in it.
local shop, shopStamp
local function gameVendors()
  local t = NS.collected().merchants
  if type(t) ~= "table" then return {} end
  local stamp = 0
  for _, rec in pairs(t) do stamp = stamp + (type(rec) == "table" and tonumber(rec.time) or 1) + 0.001 end
  if shop and shopStamp == stamp then return shop end
  shop, shopStamp = {}, stamp
  for id, rec in pairs(t) do
    id = tonumber(id)
    if id and type(rec) == "table" and type(rec.list) == "table" then
      local items = {}
      for _, line in ipairs(rec.list) do
        local f = NS.fieldsOf(line, "|")   -- text out of the saved file: anything else gives no fields
        local item, price, stack, left = tonumber(f[1]), tonumber(f[2]), tonumber(f[3]), tonumber(f[4])
        if item then
          if not stack or stack < 1 then stack = 1 end
          items[item] = { price = price and price / stack or nil, left = (left and left >= 0) and left or nil, other = f[6] == "1" }
        end
      end
      local w = NS.fieldsOf(rec.where, ";")
      local who = type(rec.player) == "string" and rec.player:match("^(%a+);") or nil
      shop[id] = { id = id, name = rec.name or "?", zone = w[1] or "", map = tonumber(w[2]), x = tonumber(w[3]), y = tonumber(w[4]),
        items = items, who = (who == "Alliance" and "A") or (who == "Horde" and "H") or nil }
    end
  end
  return shop
end

-- Where a recipe item comes from: { {kind = "v"|"d"|"q"|"o"|"w", name, zone, side, price, level}, ... }
-- A vendor read in game that sells the recipe item comes first, with the game's own price, place and stock
-- (seen = true, plus map, x, y, left, other), and replaces the shipped entry of the same name. His side is the
-- shipped one when the shipped data names him, else the faction of the character that read him (sideGuess = true).
-- A shipped vendor that was read in game and did NOT list the item is kept and marked `gone` ("not in stock when
-- you visited") rather than dropped. Assumption behind that: recipe items are mostly limited stock, the game
-- leaves a sold-out limited item out of the vendor's list altogether, and the shipped data does not say which
-- items are limited, so a missing item cannot be told from one that someone else just bought.
local function sourcesOf(r)
  local P = places()
  local text = P and P.get and P.get[r.id]
  local out, rest = {}, {}
  local byName, pat = {}, r.pat or 0
  if pat > 0 then
    for _, v in pairs(gameVendors()) do
      local it = v.items[pat]
      if it then
        out[#out + 1] = { kind = "v", name = v.name, zone = v.zone, map = v.map, x = v.x, y = v.y, price = it.price, left = it.left,
          other = it.other, seen = true, side = v.who or "B", sideGuess = true }
        byName[v.name] = out[#out]
      elseif byName[v.name] == nil then
        byName[v.name] = false   -- visited, the item was not on his list
      end
    end
  end
  for entry in (text or ""):gmatch("[^;]+") do
    local f = E.split(entry, "~")
    local k = f[1]
    if k == "v" then
      local seen = byName[f[2]]
      if seen then
        -- the shipped side knows a neutral vendor; one character's visit only shows that his own faction can buy there
        if f[4] and f[4] ~= "" then seen.side, seen.sideGuess = f[4], nil end
      else
        rest[#rest + 1] = { kind = k, name = f[2], zone = f[3], side = f[4], price = tonumber(f[5]), gone = seen == false or nil }
      end
    elseif k == "d" then
      rest[#rest + 1] = { kind = k, name = f[2], zone = f[3] }
    elseif k == "q" then
      rest[#rest + 1] = { kind = k, name = f[2], level = f[3], side = f[4] }
    elseif k == "o" or k == "w" then
      rest[#rest + 1] = { kind = k, name = f[2] }
    end
  end
  table.sort(out, function(a, b2)
    local ao, bo = open(a.side), open(b2.side)
    if ao ~= bo then return ao end
    if (a.other or false) ~= (b2.other or false) then return not a.other end   -- money alone before "and another cost"
    local ap, bp = a.price or math.huge, b2.price or math.huge
    if ap ~= bp then return ap < bp end
    return a.name < b2.name
  end)
  for _, s2 in ipairs(rest) do out[#out + 1] = s2 end
  return out
end

-- The cheapest price in copper at which this character's faction can buy the recipe item from a vendor: prices
-- read in game first (they already include the reading character's reputation discount), else the shipped price.
-- Also returns the source entry. nil when no vendor your faction can use sells it for money alone.
function NS.vendorPrice(r)
  local best, shipped
  for _, s2 in ipairs(sourcesOf(r)) do
    if s2.kind == "v" and open(s2.side) and s2.price and s2.price > 0 and not s2.other then
      if s2.seen then
        if not best or s2.price < best.price then best = s2 end
      elseif not shipped or s2.price < shipped.price then
        shipped = s2
      end
    end
  end
  best = best or shipped
  if best then return best.price, best end
  return nil
end

-- A recipe only the other faction can get: every trainer, or every vendor and quest, is theirs.
function NS.factionLocked(r)
  if not mySide() then return false end
  if r.src == "R" then
    local list = sourcesOf(r)
    if #list == 0 then return false end
    for _, s in ipairs(list) do
      -- sideGuess: a vendor only known from a visit by a character of the other faction may well be neutral
      if (s.kind ~= "v" and s.kind ~= "q") or open(s.side) or s.sideGuess then return false end
    end
    return true
  end
  local mine, other, anyTrainer = trainersOf(r)
  return not anyTrainer and #mine == 0 and other > 0
end

local function coords(n)
  return (n.x and n.y) and string.format(" (%.0f, %.0f)", n.x, n.y) or ""
end

local function sourceText(s)
  if s.kind == "v" then
    return "Sold by " .. s.name .. ((s.zone and s.zone ~= "") and (", " .. s.zone) or "") .. (s.seen and coords(s) or "")
      .. ((s.price and s.price > 0) and (" for " .. money(s.price)) or "") .. (s.other and " and another cost" or "")
      .. (s.left and (", limited stock (" .. s.left .. " when you visited)") or "") .. (s.gone and ", not in stock when you visited" or "")
  elseif s.kind == "d" then
    return "Drops from " .. s.name .. ((s.zone and s.zone ~= "") and (", " .. s.zone) or "")
  elseif s.kind == "q" then
    return "Quest: " .. s.name .. ((s.level and s.level ~= "") and (" (level " .. s.level .. ")") or "")
  elseif s.kind == "o" then
    return "Found in " .. s.name
  end
  return s.name or ""
end

-- Plain lines for a tooltip.
function NS.whereLines(r)
  local out = {}
  if r.src == "R" then
    for i, s in ipairs(sourcesOf(r)) do
      if i > 6 then break end
      out[#out + 1] = ((s.kind == "v" or s.kind == "q") and not open(s.side)) and (DIM .. sourceText(s) .. " (other faction)|r") or sourceText(s)
    end
  else
    local list, other, anyTrainer = trainersOf(r)
    if anyTrainer and #list > 0 then out[#out + 1] = "Which " .. r.prof .. " trainer teaches it is not known. Trainers:" end
    for i, n in ipairs(list) do
      if i > 4 then
        out[#out + 1] = DIM .. "and " .. (#list - 4) .. " more trainers|r"
        break
      end
      out[#out + 1] = (anyTrainer and "   " or "Trainer: ") .. n.name .. ", " .. whereIs(n) .. coords(n)
    end
    if not anyTrainer and #list == 0 and other > 0 then out[#out + 1] = RED .. "Only the other faction's trainers teach this.|r" end
  end
  if #out > 0 then out[#out + 1] = DIM .. "Places are mostly from the original game; Forever may differ.|r" end
  return out
end

-- zone name -> map id, looked up once from the game's own map list
local mapByName
local function mapFor(zone, map)
  if map then return map end   -- a trainer read in game brings his own map id
  if not mapByName then
    mapByName = {}
    if C_Map and C_Map.GetMapChildrenInfo then
      for _, root in ipairs({ 947, 946, 1414, 1415 }) do
        local kids = try(C_Map.GetMapChildrenInfo, root, nil, true)
        for _, info in ipairs(type(kids) == "table" and kids or {}) do
          if info.name and info.mapID and not mapByName[info.name] then mapByName[info.name] = info.mapID end
        end
      end
    end
  end
  return mapByName[zone]
end

-- Puts the game's own map pin on an NPC, or says where it is when the map cannot be found.
function NS.pin(n)
  local id = (n.x and n.y) and mapFor(n.zone, n.map) or nil
  if id and C_Map and C_Map.SetUserWaypoint and UiMapPoint and UiMapPoint.CreateFromCoordinates then
    local ok = pcall(function()
      C_Map.SetUserWaypoint(UiMapPoint.CreateFromCoordinates(id, n.x / 100, n.y / 100))
      if C_SuperTrack and C_SuperTrack.SetSuperTrackedUserWaypoint then C_SuperTrack.SetSuperTrackedUserWaypoint(true) end
    end)
    if ok then
      NS.say("Map pin set on " .. n.name .. ", " .. n.zone .. coords(n) .. ".")
      return true
    end
  end
  NS.say(n.name .. ": " .. whereIs(n) .. coords(n) .. " (no map pin could be set).")
  return false
end

-- Lines for the details pane: a trainer line, or a vendor you have been to, sets a map pin when clicked (and
-- carries a small map picture to say so).
local MAP_ICON = "Interface\\Icons\\INV_Misc_Map_01"
function NS.whereRows(r)
  local out = {}
  if r.src == "R" then
    for i, s in ipairs(sourcesOf(r)) do
      if i > 8 then break end
      local theirs = (s.kind == "v" or s.kind == "q") and not open(s.side)
      local row = { left = (theirs and DIM or "") .. "   " .. sourceText(s) .. (theirs and " (other faction)|r" or "") }
      if s.seen then
        row.seen = true
        row.right = GREEN .. "seen|r"
        row.action = function() NS.pin(s) end
        row.icon = MAP_ICON
        row.tip = { "Click to put a pin on the map.", "You have been to this vendor: place, price and stock are the game's own.",
          "The price is the one the game showed your character, so your reputation discount is already in it." }
      elseif s.kind == "v" then
        row.tip = { s.gone and "You have been to this vendor and the recipe was not on his list. It may be limited stock that was sold out, or Forever may not sell it here."
          or "Not visited yet: vendor, place and price are from the original game's data." }
      end
      out[#out + 1] = row
    end
  else
    local list, other, anyTrainer = trainersOf(r)
    if anyTrainer and #list > 0 then out[#out + 1] = { left = DIM .. "   which " .. r.prof .. " trainer teaches it is not known:|r" } end
    for i, n in ipairs(list) do
      if i > 8 then
        out[#out + 1] = { left = DIM .. "   and " .. (#list - 8) .. " more|r" }
        break
      end
      out[#out + 1] = { left = "   " .. n.name, right = DIM .. whereIs(n) .. coords(n) .. "|r", action = function() NS.pin(n) end, icon = MAP_ICON,
        tip = { "Click to put a pin on the map.", n.seen and "You have been to this trainer: place and recipes are the game's own."
          or "Not visited yet: the list follows the rule that a trainer teaches every recipe his rank allows; the place is from the original game." } }
    end
    if not anyTrainer and #list == 0 and other > 0 then out[#out + 1] = { left = RED .. "   Only the other faction's trainers teach this.|r" } end
  end
  return out
end
NS.trainersOf, NS.sourcesOf, NS.gameVendors = trainersOf, sourcesOf, gameVendors

-- ---- item tooltips ----------------------------------------------------------------------------------------------

local teaches   -- recipe item id -> the recipe it teaches

-- What Kebold knows about one item, as { label, value, text } entries: label and value are the two halves of a
-- tooltip line, text is the same as one sentence (NS.itemLines). An entry without text belongs to the sentence
-- of the one before it. Empty when Kebold has nothing to say about the item.
function NS.itemFacts(id)
  local out = {}
  local db = NS.data()
  if type(id) ~= "number" then return out end
  local function fact(label, value, text)
    out[#out + 1] = { label = label, value = value, text = text }
  end
  if not teaches then
    teaches = {}
    for _, r in ipairs(db.recipes) do
      if r.pat > 0 and not teaches[r.pat] then teaches[r.pat] = r end
    end
  end
  local L = E.parseLadder(NS.realmItems()[id])
  if L then
    local age = max(0, floor(((try(time) or 0) - NS.DAY_ZERO) / 86400) - L.day)
    local when = age == 0 and "" or (age == 1 and ", yesterday" or (", " .. age .. " days ago"))
    if #L.tiers > 0 then
      local avg = E.ladderAvg(L.tiers, 20)
      local more = (avg and money(avg.p) ~= money(L.tiers[1][1])) and (", " .. money(avg.p) .. " over the cheapest " .. avg.got) or ""
      fact("Auction house", "from " .. money(L.tiers[1][1]) .. more, "AH from " .. money(L.tiers[1][1]) .. more .. ", " .. L.total .. " listed" .. when)
      fact("Listed", L.total .. when)
    else
      fact("Auction house", "none listed" .. when, "AH: none listed at the last scan" .. when)
    end
  end
  -- the addon's own scan history and auctions (Sales.lua); both are absent when that file is not loaded
  local H, SA = KeboldsShinyHistory, KeboldsShinySales
  if type(H) == "table" then
    local med, days = try(H.median, id)
    local list = try(H.readings, id)
    local last = list and list[#list]
    if med and days >= 3 and last and last.low > 0 and med ~= last.low then
      fact("Usual price", money(med) .. DIM .. " (" .. days .. " scan days)|r", "Usually " .. money(med) .. " (median of " .. days .. " scan days)")
    end
    local share = try(H.drop, id)
    if share then
      fact("Price drop", RED .. floor(share * 100 + 0.5) .. "% under usual|r", RED .. "Price dropped " .. floor(share * 100 + 0.5) .. "% under its usual price|r")
    end
  end
  if type(SA) == "table" then
    local s = try(SA.summary, id)
    if s and s.finished > 0 then
      local more = s.openQty > 0 and (", " .. s.openQty .. " still listed") or ""
      fact("Your auctions", s.soldQty .. " sold of " .. s.finished .. more, "Your auctions: " .. s.soldQty .. " sold of " .. s.finished .. " finished" .. more)
    end
  end
  local it = db.items[id]
  if it and it.vp then fact("Vendor sells", money(it.vp), "Vendors sell it for " .. money(it.vp)) end
  local r = db.maker[id]
  if r and not (it and it.raw) then
    local c = NS.state(r.prof)
    -- the Craft page's figures: the way of getting the parts that earns the most per hour, unless the player chose
    local x, mode = c.ctx.info(r), "auto"
    if c.ctx.bestInfo then x, mode = c.ctx.bestInfo(r) end
    local note = mode == "buy" and ", parts bought" or (mode == "craft" and ", parts made" or "")
    local known = c.st.known and c.st.known[r.id]
    fact("Craft cost", (x.cost and money(x.cost) or "not priced") .. DIM .. " (" .. r.prof .. " " .. r.learn .. (known and ", known" or "") .. note .. ")|r",
      "Made with " .. r.prof .. " (" .. r.learn .. (known and ", known" or "") .. note .. "): materials " .. (x.cost and money(x.cost) or "not priced")
        .. (x.p and (", profit " .. signed(x.p) .. (x.way == "AH" and " at the AH" or (x.way == "DE" and " disenchanted" or " at a vendor"))) or ""))
    if x.p then
      local ph = (x.secs and x.secs > 0) and x.p / x.secs * 3600 or nil
      fact("Profit", signed(x.p) .. DIM .. (x.way == "AH" and " at the AH" or (x.way == "DE" and " disenchanted" or " at a vendor")) .. "|r" .. (ph and ("  " .. signed(ph) .. DIM .. " /h|r") or ""))
    end
  end
  -- what disenchanting it would give (LedgerDisenchant.lua): only for green, blue and epic armour and weapons
  if NS.deValue then
    local dv, dknown, dd = NS.deValue(id)
    if dd then
      local mark = dd.o.est and "~" or ""
      if dknown then
        fact("Disenchants for", mark .. money(dv), "Disenchants for about " .. mark .. money(dv))
      else
        fact("Disenchants for", DIM .. "materials not scanned|r", "Disenchants for about ? (its materials are not scanned)")
      end
    end
  end
  local t = teaches[id]
  if t then
    local c = NS.state(t.prof)
    local known = c.st.known and c.st.known[t.id]
    local state = known and (GREEN .. ", you know it|r") or (c.st.seen and ", not known yet" or "")
    fact("Teaches", t.name .. DIM .. " (" .. t.prof .. " " .. t.learn .. ")|r" .. state, "Teaches " .. t.name .. " (" .. t.prof .. " " .. t.learn .. ")" .. state)
  end
  return out
end

-- The same as sentences, one a line.
function NS.itemLines(id)
  local out = {}
  for _, f in ipairs(NS.itemFacts(id)) do
    if f.text then out[#out + 1] = f.text end
  end
  return out
end

-- Under the game's own lines: a gap, a gold "Kebold's Shiny" and then label on the left, value on the right.
-- Short mode shows the first two; holding Shift shows them all.
local function onItemTooltip(tooltip, data)
  local S = settings()
  if S.tooltips == false then return end
  if tooltip ~= GameTooltip and tooltip ~= ItemRefTooltip then return end
  local id = type(data) == "table" and data.id or nil
  local facts = NS.itemFacts(id)
  if #facts == 0 then return end
  local count = #facts
  if S.tipMode == "short" and not (type(IsShiftKeyDown) == "function" and IsShiftKeyDown()) then count = min(2, count) end
  if type(GameTooltip_AddBlankLineToTooltip) == "function" then GameTooltip_AddBlankLineToTooltip(tooltip) else tooltip:AddLine(" ") end
  tooltip:AddLine("Kebold's Shiny", 1, 0.82, 0)
  for i = 1, count do
    tooltip:AddDoubleLine(facts[i].label, UI.show(facts[i].value), 1, 0.82, 0, 1, 1, 1)
  end
  if count < #facts then tooltip:AddLine(DIM .. "Hold Shift for " .. (#facts - count) .. " more|r") end
  tooltip:Show()
end

if TooltipDataProcessor and TooltipDataProcessor.AddTooltipPostCall and Enum and Enum.TooltipDataType and Enum.TooltipDataType.Item then
  pcall(TooltipDataProcessor.AddTooltipPostCall, Enum.TooltipDataType.Item, function(tooltip, data)
    pcall(onItemTooltip, tooltip, data)   -- a mistake here must never break the game's tooltips
  end)
end

-- ---- the strip above the profession window -----------------------------------------------------------------------

local strip, stripRecipe, stripVersion

-- Where the figures are asked to sit: "pane" (inside the recipe pane, the default), "top" (the strip above the
-- window) or "off". An older saved false means off.
function NS.stripMode()
  local m = settings().strip
  if m == false or m == "off" then return "off" end
  return m == "top" and "top" or "pane"
end

-- The recipe pane of the profession window (Blizzard's frame, only read), or nil.
local function schematicForm()
  local pf = ProfessionsFrame
  local page = type(pf) == "table" and pf.CraftingPage or nil
  local form = type(page) == "table" and page.SchematicForm or nil
  return type(form) == "table" and form or nil
end
NS.schematicForm = schematicForm

-- The recipe selected in the profession window, read from Blizzard's frame without touching it.
local function selectedRecipe()
  local pf = ProfessionsFrame
  if type(pf) ~= "table" or not (pf.IsShown and pf:IsShown()) then return nil end
  local form = schematicForm()
  if not form then return nil end
  local info = form.currentRecipeInfo
  if type(info) ~= "table" and type(form.GetRecipeInfo) == "function" then info = try(form.GetRecipeInfo, form) end
  return type(info) == "table" and info.recipeID or nil
end
NS.selectedRecipe = selectedRecipe

-- Two lines for one recipe; nil when Kebold does not have it.
function NS.stripText(recipeID)
  local r = NS.data().byId[recipeID]
  if not r then return nil end
  local c = NS.state(r.prof)
  local f = NS.figures(c, r)
  local x = f.x
  local skill = c.st.skill or c.from
  local one = GOLD .. "Kebold|r  materials " .. (x.cost and money(x.cost) or (RED .. "not priced|r"))
    .. "   vendor " .. (r.sell and money(r.sell * f.mk) or "?")
    .. "   AH " .. (x.ahp and (money(x.ahp * f.mk) .. DIM .. " (" .. (x.listed or 0) .. ")|r") or (DIM .. "-|r"))
  local two = "profit " .. signed(x.p) .. (x.way and (DIM .. NS.wayShort(x.way) .. "|r") or "")
    .. "   per hour " .. (f.ph and signed(f.ph) or (DIM .. "-|r"))
    .. (r.col and string.format("   chance of a point %.0f%% at %d", 100 * c.ctx.chanceAt(r, skill), skill) or "")
  local w = x.cost and x.p and NS.worthOf and NS.worthOf(c, r)
  if w and w.worth ~= math.huge then two = two .. "   worth making " .. (w.known and "" or "~") .. w.worth end
  if f.mode ~= "auto" then two = two .. DIM .. (f.mode == "buy" and "   parts bought" or "   parts made") .. "|r" end
  return one, two
end

-- The same as up to seven cells, each a label over a value; nil when Kebold does not have the recipe.
function NS.stripCells(recipeID)
  local r = NS.data().byId[recipeID]
  if not r then return nil end
  local c = NS.state(r.prof)
  local f = NS.figures(c, r)
  local x = f.x
  local skill = c.st.skill or c.from
  local out = {
    { label = "Materials" .. (f.mode == "buy" and ", parts bought" or (f.mode == "craft" and ", parts made" or "")), value = x.cost and money(x.cost) or (RED .. "not priced|r") },
    { label = "Vendor", value = r.sell and money(r.sell * f.mk) or (DIM .. "?|r") },
    { label = "AH" .. (x.listed and (" (" .. x.listed .. " listed)") or ""), value = x.ahp and money(x.ahp * f.mk) or (DIM .. "-|r") },
    { label = "Profit" .. (x.way and ("," .. NS.wayShort(x.way)) or ""), value = signed(x.p) },
    { label = "Per hour", value = f.ph and signed(f.ph) or (DIM .. "-|r") },
  }
  if r.col then out[#out + 1] = { label = "Chance of a point at " .. skill, value = string.format("%.0f%%", 100 * c.ctx.chanceAt(r, skill)) } end
  local w = x.cost and x.p and NS.worthOf and NS.worthOf(c, r)
  if w and w.worth ~= math.huge then out[#out + 1] = { label = "Worth making", value = (w.known and "" or "~") .. w.worth } end
  return out
end

local STRIP_CELLS, STRIP_CELL_W = 7, 86

local function createStrip()
  -- anchored to the profession window, not inside it; a tooltip-style box where the client has one
  local ok, f
  if UI.has("TooltipBackdropTemplate") then ok, f = pcall(CreateFrame, "Frame", "KeboldsShinyStrip", UIParent, "TooltipBackdropTemplate") end
  if not (ok and type(f) == "table") and UI.has("BackdropTemplate") then
    ok, f = pcall(CreateFrame, "Frame", "KeboldsShinyStrip", UIParent, "BackdropTemplate")
    if ok and type(f) == "table" and type(f.SetBackdrop) == "function" then
      pcall(f.SetBackdrop, f, { bgFile = "Interface\\Tooltips\\UI-Tooltip-Background", edgeFile = "Interface\\Tooltips\\UI-Tooltip-Border", tile = true, tileSize = 16,
        edgeSize = 12, insets = { left = 3, right = 3, top = 3, bottom = 3 } })
      if type(f.SetBackdropColor) == "function" then pcall(f.SetBackdropColor, f, 0.05, 0.05, 0.07, 0.92) end
    end
  end
  if not (ok and type(f) == "table") then
    f = CreateFrame("Frame", "KeboldsShinyStrip", UIParent)
    local bg = f:CreateTexture(nil, "BACKGROUND")
    bg:SetAllPoints()
    bg:SetColorTexture(0.05, 0.05, 0.07, 0.9)
  end
  f:SetSize(STRIP_CELLS * STRIP_CELL_W + 16, 36)
  f:SetFrameStrata("HIGH")
  f:SetPoint("BOTTOMLEFT", ProfessionsFrame, "TOPLEFT", 8, 2)
  f.cells = {}
  for i = 1, STRIP_CELLS do
    local cell = {}
    cell.label = f:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
    cell.label:SetPoint("TOPLEFT", 8 + (i - 1) * STRIP_CELL_W, -5)
    cell.label:SetWidth(STRIP_CELL_W - 4)
    cell.label:SetJustifyH("LEFT")
    cell.label:SetWordWrap(false)
    cell.value = f:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
    cell.value:SetPoint("TOPLEFT", 8 + (i - 1) * STRIP_CELL_W, -18)
    cell.value:SetWidth(STRIP_CELL_W - 4)
    cell.value:SetJustifyH("LEFT")
    cell.value:SetWordWrap(false)
    f.cells[i] = cell
  end
  return f
end

local stripOn = false   -- our own note of whether the strip is up (a new frame counts as shown before it is used)
local function hideStrip()
  if strip and stripOn then
    stripOn = false
    strip:Hide()
    if NS.placeProfButton then pcall(NS.placeProfButton, nil) end
  end
  stripRecipe = nil
end

-- Where the figures really sit: "pane" only when that was asked for and the recipe pane was found and built;
-- a client without the pane gets the strip above the window ("top") by itself.
function NS.stripPlace()
  local mode = NS.stripMode()
  if mode ~= "pane" then return mode end
  return (NS.paneUsable and NS.paneUsable()) and "pane" or "top"
end

local lastPlace
local function updateStrip()
  local mode = NS.stripMode()
  local id = mode ~= "off" and selectedRecipe() or nil
  local inPane = false
  if mode == "pane" and NS.paneUpdate then
    local ok, used = pcall(NS.paneUpdate, id)
    inPane = ok and used and true or false
  elseif NS.paneHide then
    pcall(NS.paneHide)
  end
  local place = inPane and "pane" or (mode == "off" and "off" or "top")
  if place ~= lastPlace then   -- the button outside the window comes and goes with the block inside it
    lastPlace = place
    if NS.onProfessionShown then pcall(NS.onProfessionShown) end
  end
  if inPane then
    hideStrip()
    return
  end
  local cells = id and NS.stripCells(id) or nil
  if not cells then
    hideStrip()
    return
  end
  if not strip then strip = createStrip() end
  for i, cell in ipairs(strip.cells) do
    local c = cells[i]
    cell.label:SetText(c and c.label or "")
    cell.value:SetText(c and UI.show(c.value) or "")
  end
  if not stripOn then
    stripOn = true
    strip:Show()
    if NS.placeProfButton then pcall(NS.placeProfButton, strip) end   -- the Kebold button sits at the strip's right end
  end
  stripRecipe = id
end

-- After a change of the setting, and when the selected recipe changes: do not wait for the next tick.
function NS.stripRefresh()
  pcall(updateStrip)
end

local function tick()
  pcall(updateStrip)
  C_Timer.After(0.5, tick)
end
C_Timer.After(2, tick)

-- Outside the Kebold window he crafts as himself: the item tooltip's lines and the strip above the profession
-- window show the character's own figures (NS.asMe), whatever "Plan for" profile the window is showing.
for _, name in ipairs({ "itemFacts", "stripText", "stripCells" }) do
  local inner = NS[name]
  if type(inner) == "function" and type(NS.asMe) == "function" then
    NS[name] = function(...) return NS.asMe(inner, ...) end
  end
end
